{
  "assessment": "Germany's economy continues to experience stagnation with negative annualised growth, though our recent push into infrastructure and research is helping to lay the groundwork for recovery. Our fiscal deficit is slightly elevated at 4.4% of GDP, requiring careful fiscal management while we stimulate growth. Public approval remains stable, and our international partnerships within the EU and NATO are strong. We will maintain our support for Ukraine diplomatically and build upon our robust bilateral ties with France and Austria, while keeping up our standing economic growth measures.",
  "directives": [
    {
      "type": "invest_infrastructure",
      "target": null,
      "amount": 0.5,
      "sub": "",
      "order": "Increase infrastructure investment by an additional 0.5% of GDP to stimulate economic activity."
    },
    {
      "type": "invest_research",
      "target": null,
      "amount": 0.5,
      "sub": "",
      "order": "Increase research and development investment by an additional 0.5% of GDP to boost long-term productivity."
    },
    {
      "type": "monetary_policy",
      "target": null,
      "amount": -0.25,
      "sub": "",
      "order": "Encourage the central bank to ease monetary policy by 25 basis points to support investment."
    }
  ],
  "cables": [
    {
      "to": "FRA",
      "private": true,
      "text": "We deeply value our partnership and look forward to advancing joint European initiatives for economic renewal."
    },
    {
      "to": "AUT",
      "private": true,
      "text": "Thank you for your kind message. We remain committed to our close bilateral partnership and regional stability."
    },
    {
      "to": "UKR",
      "private": true,
      "text": "Germany remains steadfast in its diplomatic and humanitarian support for Ukraine within the European framework."
    }
  ],
  "public_statement": "The Federal Government is fully committed to revitalising Germany's economic dynamism through targeted investments in infrastructure and future technologies. By supporting innovation and maintaining our strong alliances within Europe, we ensure sustainable prosperity and security for all citizens.",
  "standing_orders": [
    {
      "when": "growth_below:0",
      "do": {
        "type": "invest_infrastructure",
        "target": null,
        "amount": 0.5,
        "sub": "",
        "order": "Invest an additional 0.5% of GDP in infrastructure when growth is negative."
      }
    }
  ],
  "detailed_report": "economy"
}
